import type { Store } from '../store/sqlite.ts'

export interface A2AEnvelope {
  from: string
  to: string
  body: unknown
  /** Generated by `A2ARouter.send` when absent. */
  id?: string
  at?: string
}

export interface A2ADelivery {
  envelope: A2AEnvelope
  status: 'delivered' | 'unroutable' | 'failed'
  delivered: number
  persisted: boolean
  error?: string
}

const MAX_BODY_BYTES = 64 * 1024

/**
 * In-process A2A envelope router (T50). The wire transport between processes
 * is external; this class owns validation, persistence, and local dispatch so
 * an adapter only has to move bytes.
 */
export class A2ARouter {
  readonly history: A2AEnvelope[]
  private readonly recipients = new Map<string, Set<(envelope: A2AEnvelope) => void>>()
  private fallbackId = 0

  constructor(private readonly store?: Store) {
    this.history = store ? store.listDocs<A2AEnvelope>('a2a') : []
  }

  register(recipient: string, handler: (envelope: A2AEnvelope) => void): () => void {
    if (!recipient.trim()) throw new Error('A2A recipient must not be empty')
    let handlers = this.recipients.get(recipient)
    if (!handlers) {
      handlers = new Set()
      this.recipients.set(recipient, handlers)
    }
    handlers.add(handler)
    return () => {
      handlers.delete(handler)
      if (handlers.size === 0) this.recipients.delete(recipient)
    }
  }

  /** Low-level dispatch: validates and calls every local handler. Unknown targets are a no-op. */
  route(envelope: A2AEnvelope): A2AEnvelope {
    validate(envelope)
    this.history.push(envelope)
    if (this.store && envelope.id) this.store.putDoc('a2a', envelope.id, envelope)
    for (const handler of this.recipients.get(envelope.to) ?? []) handler(envelope)
    return envelope
  }

  /** Durable send with an explicit delivery result. Used by `Runtime.sendA2A`. */
  send(envelope: A2AEnvelope): A2ADelivery {
    const prepared: A2AEnvelope = {
      ...envelope,
      id: envelope.id ?? this.nextId(),
      at: envelope.at ?? new Date().toISOString(),
    }
    validate(prepared)
    const handlers = [...(this.recipients.get(prepared.to) ?? [])]
    this.history.push(prepared)
    if (this.store && prepared.id) this.store.putDoc('a2a', prepared.id, prepared)
    if (handlers.length === 0) {
      return { envelope: prepared, status: 'unroutable', delivered: 0, persisted: this.store != null }
    }
    let delivered = 0
    try {
      for (const handler of handlers) {
        handler(prepared)
        delivered += 1
      }
    } catch (error) {
      return {
        envelope: prepared,
        status: 'failed',
        delivered,
        persisted: this.store != null,
        error: error instanceof Error ? error.message : String(error),
      }
    }
    return { envelope: prepared, status: 'delivered', delivered, persisted: this.store != null }
  }

  list(): A2AEnvelope[] {
    return this.store ? this.store.listDocs<A2AEnvelope>('a2a') : [...this.history]
  }

  private nextId(): string {
    if (this.store) return this.store.nextId('a2a')
    this.fallbackId += 1
    return `a2a_local_${this.fallbackId}`
  }
}

function validate(envelope: A2AEnvelope): void {
  if (!envelope || typeof envelope !== 'object') throw new Error('A2A envelope must be an object')
  if (!envelope.from?.trim()) throw new Error('A2A envelope needs a from address')
  if (!envelope.to?.trim()) throw new Error('A2A envelope needs a to address')
  let size: number
  try {
    size = JSON.stringify(envelope.body ?? null).length
  } catch {
    throw new Error('A2A envelope body is not serializable')
  }
  if (size > MAX_BODY_BYTES) throw new Error(`A2A envelope body exceeds ${MAX_BODY_BYTES} bytes`)
}
